query:
SELECT email, COUNT(*) as count, GROUP_CONCAT(id ORDER BY id) as ids
FROM users
WHERE email IS NOT NULL
GROUP BY email
HAVING COUNT(*) > 1
ORDER BY count DESC
LIMIT 20;

SELECT COUNT(*) as null_email_users FROM users WHERE email IS NULL;
SELECT COUNT(*) as total_users FROM users;
SELECT COUNT(*) as real_users FROM users WHERE email IS NOT NULL;

